// Minimal bootstrap bundle placeholder for Secret Santa theme.
export const version = '5.3.3-custom';

export function initTooltips() {
  // Tooltips are not required for the current UI but the function is left
  // here to avoid runtime errors when called from tests or extensions.
  if (process.env.NODE_ENV !== 'production') {
    // eslint-disable-next-line no-console
    console.warn('Bootstrap JS placeholder: tooltips are not implemented.');
  }
}
